def f(g):
    bg=4
    H,W=len(g),len(g[0]); res=[[bg]*W for _ in range(H)]
    degmax=0; kept=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg:
                n=sum(1 for di,dj in((1,0),(-1,0),(0,1),(0,-1)) if 0<=i+di<H and 0<=j+dj<W and g[i+di][j+dj]==g[i][j])
                if n>=degmax: degmax=max(degmax,n)
                if n==degmax: kept.append((i,j))
    for i,j in kept: res[i][j]=g[i][j]
    return res
